from abc import ABCMeta, abstractmethod
from six import with_metaclass


class BmcConfiguration(object):
    pass


class Bmc(with_metaclass(ABCMeta, object)):
    """
    Base "interface" class for all BMC interface types, enforcing proper interface methods,
     and adding default attributes
    """
    protocol = None

    @abstractmethod
    def login(self):
        raise NotImplementedError

    @abstractmethod
    def logout(self):
        raise NotImplementedError


class BmcResponse(object):
    """
    Default response facade that can be used by all interfaces
    """
    def __init__(self, status, data):
        """

        :param int status: Status code based on HTTP Status Codes
        :param dict data: Data returned by endpoint function
        """
        self.status = status
        self.data = data

    def __bool__(self):
        return self.status

    # Python 2to3 compatibility , __bool__ in python3 , __nonzero__ in python2
    __nonzero__ = __bool__
